/**
 * The venue's crowd atlas, painted from code (original; deterministic; nothing downloaded, traced or generated by a model).
 *
 * The atlas holds the front elevation of the two crowd tiers of one 6-degree wedge, VARIANTS times (different seats and
 * shirts, so 54 wedges do not repeat): a row of lower-tier tiles above a row of upper-tier tiles, and a 4 x 4 px white
 * patch in the bottom-right corner for every surface that carries only a vertex colour. Albedo only: no light and no
 * shadow are painted, because the stage lights and shades it (ambient occlusion lives in the vertex colours).
 *
 * Each tile maps azimuth across its width (the wedge) and height up the tier along its height, like the UVs written by
 * scripts/blender/venue/build_venue.py. Rows are painted from the back to the front so a front row hides the legs of
 * the row behind it. A person is a body, a head and hair; seats are 0.62 m apart, bodies 0.5 m wide; the aisle at the
 * wedge's left edge is 1.4 m of light stairs.
 *
 * A tiny software rasteriser with 1 px coverage anti-aliasing keeps this free of any canvas dependency.
 */

const SHIRTS = [
  [59, 47, 201],
  [232, 144, 26],
  [242, 242, 238],
  [255, 179, 71],
  [95, 205, 242],
  [230, 92, 128],
  [255, 212, 110],
  [46, 51, 66],
  [125, 214, 179],
];
const SHIRT_WEIGHT = [0.2, 0.17, 0.14, 0.08, 0.08, 0.08, 0.07, 0.1, 0.08];
const SKINS = [
  [231, 191, 155],
  [216, 164, 126],
  [200, 140, 99],
  [180, 118, 79],
  [157, 99, 64],
  [134, 84, 54],
  [111, 69, 44],
];
const TROUSERS = [
  [34, 40, 66],
  [58, 52, 44],
  [76, 82, 100],
  [28, 30, 38],
];
const HAIR = [
  [20, 16, 14],
  [38, 28, 22],
  [60, 44, 32],
  [96, 80, 66],
];

export function mulberry32(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

class Raster {
  constructor(w, h) {
    this.w = w;
    this.h = h;
    this.px = new Uint8Array(w * h * 4);
  }

  blend(x, y, c, a) {
    if (x < 0 || y < 0 || x >= this.w || y >= this.h || a <= 0) return;
    const i = (y * this.w + x) * 4;
    const k = Math.min(1, a);
    this.px[i] = Math.round(this.px[i] * (1 - k) + c[0] * k);
    this.px[i + 1] = Math.round(this.px[i + 1] * (1 - k) + c[1] * k);
    this.px[i + 2] = Math.round(this.px[i + 2] * (1 - k) + c[2] * k);
    this.px[i + 3] = 255;
  }

  /** Axis-aligned rectangle with fractional edges (coverage anti-aliasing), clipped to [cx0, cx1) x [cy0, cy1). */
  rect(x0, y0, x1, y1, c, clip) {
    const [cx0, cy0, cx1, cy1] = clip;
    x0 = Math.max(x0, cx0);
    y0 = Math.max(y0, cy0);
    x1 = Math.min(x1, cx1);
    y1 = Math.min(y1, cy1);
    if (x1 <= x0 || y1 <= y0) return;
    for (let y = Math.floor(y0); y < Math.ceil(y1); y++) {
      const cy = Math.min(y + 1, y1) - Math.max(y, y0);
      for (let x = Math.floor(x0); x < Math.ceil(x1); x++) {
        this.blend(x, y, c, cy * (Math.min(x + 1, x1) - Math.max(x, x0)));
      }
    }
  }

  disc(cx, cy, r, c, clip) {
    const [cx0, cy0, cx1, cy1] = clip;
    for (let y = Math.max(cy0, Math.floor(cy - r - 1)); y < Math.min(cy1, Math.ceil(cy + r + 1)); y++) {
      for (let x = Math.max(cx0, Math.floor(cx - r - 1)); x < Math.min(cx1, Math.ceil(cx + r + 1)); x++) {
        const d = Math.hypot(x + 0.5 - cx, y + 0.5 - cy);
        this.blend(x, y, c, Math.max(0, Math.min(1, r + 0.5 - d)));
      }
    }
  }
}

const scale = (c, f) => c.map((v) => Math.max(0, Math.min(255, Math.round(v * f))));

/**
 * @param {object} wedge the parsed wedge.json (constants, atlas)
 * @param {{ width?: number, seed?: number }} [opt] width of the atlas in px (height keeps the 2:1 shape)
 * @returns {{ width: number, height: number, rgba: Uint8Array }}
 */
export function paintAtlas(wedge, opt = {}) {
  const width = opt.width ?? wedge.atlas.w;
  const height = width / 2;
  const seed = opt.seed ?? 2026;
  const R = new Raster(width, height);
  for (let i = 0; i < width * height; i++) R.px.set([74, 84, 128, 255], i * 4);
  const { wedgeRad, tiers } = wedge.constants;

  for (const [name, t] of Object.entries(tiers)) {
    wedge.atlas.tiles[name].forEach((rect, variant) => {
      const [u0, v0, u1, v1] = rect;
      const tx0 = Math.round(u0 * width);
      const ty0 = Math.round(v0 * height);
      const tw = Math.round((u1 - u0) * width);
      const th = Math.round((v1 - v0) * height);
      const clip = [tx0, ty0, tx0 + tw, ty0 + th];
      const rand = mulberry32(seed + (name === 'lower' ? 17 : 91) * (variant + 1));
      const tierH = t.y1 - t.y0;
      const yPx = (y) => ty0 + (1 - (y - t.y0) / tierH) * th;
      const pickShirt = () => {
        let r = rand();
        for (let i = 0; i < SHIRT_WEIGHT.length; i++) {
          r -= SHIRT_WEIGHT[i];
          if (r <= 0) return SHIRTS[i];
        }
        return SHIRTS[SHIRTS.length - 1];
      };
      // Concrete behind the rows, a little darker towards the back of the tier.
      R.rect(tx0, ty0, tx0 + tw, ty0 + th, [74, 84, 128], clip);
      for (let k = t.rows - 1; k >= 0; k--) {
        const ra = t.r0 + ((t.r1 - t.r0) * k) / t.rows;
        const rb = t.r0 + ((t.r1 - t.r0) * (k + 1)) / t.rows;
        const ya = t.y0 + (tierH * k) / t.rows;
        const yb = t.y0 + (tierH * (k + 1)) / t.rows;
        const concrete = scale([80, 90, 136], 1 - 0.12 * (k / t.rows));
        R.rect(tx0, yPx(yb), tx0 + tw, yPx(ya) + 0.5, concrete, clip);
        // The tread edge: a thin dark line where the next riser starts.
        R.rect(tx0, yPx(yb) - 0.4, tx0 + tw, yPx(yb) + 0.4, scale(concrete, 0.7), clip);
        const rs = ra + (rb - ra) * 0.42;
        const arc = wedgeRad * rs;
        const mPx = tw / arc; // pixels per metre across this row
        const vPx = th / tierH; // pixels per metre up the tier
        const aisle = 1.4;
        R.rect(tx0, yPx(yb), tx0 + aisle * mPx, yPx(ya), scale([150, 152, 165], 1 - 0.1 * (k / t.rows)), clip);
        const seats = Math.floor((arc - aisle) / 0.62);
        for (let s = 0; s < seats; s++) {
          if (rand() < 0.16) continue;
          const cxm = aisle + (s + 0.5) * 0.62;
          const cx = tx0 + cxm * mPx;
          const shirt = scale(pickShirt(), 0.7 + rand() * 0.25);
          const skin = SKINS[Math.floor(rand() * SKINS.length)];
          const hair = HAIR[Math.floor(rand() * HAIR.length)];
          const body = ((0.5 + (rand() - 0.5) * 0.06) * mPx) / 2;
          const base = yPx(yb) + (rand() - 0.5) * 0.05 * vPx;
          const trousers = TROUSERS[Math.floor(rand() * TROUSERS.length)];
          // Knees showing below the torso, then the torso (shaded darker towards the seat), the shoulders and the head.
          R.rect(cx - body * 0.86, base + 0.02 * vPx, cx + body * 0.86, base + 0.2 * vPx, trousers, clip);
          R.rect(cx - body, base - 0.46 * vPx, cx + body, base + 0.04 * vPx, scale(shirt, 0.86), clip);
          R.rect(cx - body, base - 0.46 * vPx, cx + body, base - 0.2 * vPx, shirt, clip);
          R.rect(cx - body * 1.08, base - 0.46 * vPx, cx + body * 1.08, base - 0.36 * vPx, scale(shirt, 1.08), clip);
          const hr = Math.max(0.9, 0.1 * mPx);
          const hy = base - 0.46 * vPx - hr * 0.95;
          R.disc(cx, hy, hr, hair, clip);
          R.disc(cx, hy + hr * 0.22, hr * 0.88, skin, clip);
        }
      }
    });
  }
  // The neutral patch every vertex-coloured surface samples.
  R.rect(width - 4, height - 4, width, height, [255, 255, 255], [0, 0, width, height]);
  return { width, height, rgba: R.px };
}
